#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>
using namespace std;

class Solution {
public:
    vector<string> alertNames(vector<string>& keyName, vector<string>& keyTime) {
        unordered_map<string, vector<int>> events;
        int n = keyName.size();
        for (int i = 0; i < n; ++i) {
            int h = stoi(keyTime[i].substr(0, 2));
            int m = stoi(keyTime[i].substr(3, 2));
            events[keyName[i]].push_back(h * 60 + m);
        }
        vector<string> ans;
        for (auto& [name, times] : events) {
            sort(times.begin(), times.end());
            for (size_t i = 0; i + 2 < times.size(); ++i) {
                if (times[i + 2] - times[i] <= 60) {
                    ans.push_back(name);
                    break;
                }
            }
        }
        sort(ans.begin(), ans.end());
        return ans;
    }
};

import java.util.*;

class Solution {
    public List<String> alertNames(String[] keyName, String[] keyTime) {
        Map<String, List<Integer>> events = new HashMap<>();
        int n = keyName.length;
        for (int i = 0; i < n; ++i) {
            String[] parts = keyTime[i].split(":");
            int mins = Integer.parseInt(parts[0]) * 60 + Integer.parseInt(parts[1]);
            events.computeIfAbsent(keyName[i], k -> new ArrayList<>()).add(mins);
        }
        List<String> ans = new ArrayList<>();
        for (Map.Entry<String, List<Integer>> entry : events.entrySet()) {
            List<Integer> times = entry.getValue();
            Collections.sort(times);
            for (int i = 0; i + 2 < times.size(); ++i) {
                if (times.get(i + 2) - times.get(i) <= 60) {
                    ans.add(entry.getKey());
                    break;
                }
            }
        }
        Collections.sort(ans);
        return ans;
    }
}

