var alertNames = function(keyName, keyTime) {
    const events = new Map();
    const n = keyName.length;
    for (let i = 0; i < n; ++i) {
        const [h, m] = keyTime[i].split(':').map(Number);
        const mins = h * 60 + m;
        if (!events.has(keyName[i])) events.set(keyName[i], []);
        events.get(keyName[i]).push(mins);
    }
    const ans = [];
    for (const [name, times] of events.entries()) {
        times.sort((a, b) => a - b);
        for (let i = 0; i + 2 < times.length; ++i) {
            if (times[i + 2] - times[i] <= 60) {
                ans.push(name);
                break;
            }
        }
    }
    ans.sort();
    return ans;
};
